package main

import "fmt"

func main() {
	var p *int
	if p == nil {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

package main

import "fmt"

func main() {
	p := new(int)
	fmt.Println(*p)
	if p == nil {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

package main

import "fmt"

func inc(n int) {
	n++
}

func incp(n *int) {
	*n++
}

func main() {
	a, b := 1, 1
	inc(a)
	incp(&b)
	fmt.Println(a)
	fmt.Println(b)
}

package main

import "fmt"

type S struct{ N int }

func main() {
	s := S{N: 4}
	p := &s
	p.N = 8
	fmt.Println(s.N)
}

package main

import "fmt"

func main() {
	p := &struct{ N int }{N: 5}
	fmt.Println(p.N)
}

package main

import "fmt"

func main() {
	p, q := new(int), new(int)
	if p == q {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
	if *p == *q {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

package main

import "fmt"

func main() {
	s := []int{1, 2, 3}
	p := &s[1]
	*p = 9
	fmt.Println(s[1])
}

package main

import "fmt"

type S struct{ N int }

func bump(s S) {
	s.N = 9
}

func main() {
	s := S{N: 1}
	bump(s)
	fmt.Println(s.N)
}

package main

import "fmt"

type S struct{ N int }

func bump(s *S) {
	s.N = 9
}

func main() {
	s := S{N: 1}
	bump(&s)
	fmt.Println(s.N)
}

package main

import "fmt"

func main() {
	var p *int
	q := new(int)
	if p == nil {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
	if q == nil {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
	fmt.Println(*q)
}

package main

import "fmt"

func main() {
	x := 2
	p, q := &x, &x
	if p == q {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

package main

import "fmt"

func main() {
	a := [3]int{2, 4, 6}
	p := &a
	fmt.Println((*p)[1])
	fmt.Println(p[2])
}

package main

import "fmt"

func main() {
	defer func() {
		if recover() != nil {
			fmt.Println(1)
		} else {
			fmt.Println(0)
		}
	}()
	var p *int
	fmt.Println(*p)
}

